def fill_template(template, variables):
    result = template
    for key, value in variables.items():
        token = '{' + str(key) + '}'
        result = result.replace(token, str(value))
    return result

def choose_mode(task):
    fixed = {'summarize', 'classify', 'extract'}
    dynamic = {'research', 'investigate', 'triage'}
    if task in fixed:
        return 'chain'
    if task in dynamic:
        return 'agent'
    return 'unknown'

def is_tool_allowed(tool_name, role):
    policy = {
        'read_docs': {'viewer', 'analyst', 'admin'},
        'create_ticket': {'analyst', 'admin'},
        'delete_ticket': {'admin'},
    }
    allowed_roles = policy.get(tool_name)
    if not allowed_roles:
        return False
    return role in allowed_roles

def validate_response(payload):
    required = ('answer', 'confidence', 'citations')
    for key in required:
        if key not in payload:
            return [False, {'error': 'missing_field'}]

    answer = payload.get('answer')
    if not isinstance(answer, str) or not answer.strip():
        return [False, {'error': 'invalid_answer'}]

    confidence = payload.get('confidence')
    if not isinstance(confidence, (int, float)) or not (0 <= confidence <= 1):
        return [False, {'error': 'invalid_confidence'}]

    citations = payload.get('citations')
    if not isinstance(citations, list):
        return [False, {'error': 'invalid_citations'}]

    return [True, payload]
